using ExecutiveCommand.Core.Model;

namespace ExecutiveCommand.Core.Engine;

/// <summary>
/// Quarterly performance review. Every score is computed from recorded decisions and measurable
/// results, and every review lists the evidence it used. Nothing here is generated by the AI.
/// </summary>
public static class PerformanceEngine
{
    public const decimal SavingsTarget = 400_000m;

    public static PerformanceReview QuarterlyReview(SimulationEngine e)
    {
        var s = e.State;
        var periodStart = s.Reviews.Count > 0 ? s.Reviews[^1].Date.AddDays(1) : s.StartDate;
        var review = Compute(s, periodStart, s.CurrentDate);
        review.Id = s.NewId("REV");
        s.Reviews.Add(review);

        s.Metrics.BoardConfidence = SimulationEngine.Clamp(s.Metrics.BoardConfidence + (review.Overall - 55) / 4.0);
        s.Player.Reputation = SimulationEngine.Clamp(s.Player.Reputation + (review.Overall - 55) / 6.0);
        e.AdjustTrust(ExecRole.CEO, (review.Overall - 55) / 8.0);

        e.Notify(MessageKind.Review, ExecRole.CEO, $"Performance review — {review.Period}",
            $"Rating: {Label(review.Rating)} (overall {review.Overall:0}).\n" +
            $"Decision quality {review.DecisionQuality:0} · Delivery {review.Delivery:0} · Financial stewardship {review.FinancialStewardship:0} · Risk management {review.RiskManagement:0}\n\n" +
            review.ReviewerComment + "\n\nEvidence:\n• " + string.Join("\n• ", review.Evidence), review.Id);
        e.Remember("review", $"Quarterly review {review.Period}: {Label(review.Rating)} ({review.Overall:0}).", new[] { Topics.Performance }, new[] { ExecRole.CEO }, 2);

        int n = s.Reviews.Count;
        if (review.Rating == ReviewRating.ExceedsExpectations && !s.Player.Achievements.Contains("Exceeds Expectations"))
            s.Player.Achievements.Add("Exceeds Expectations");
        bool twoUnsat = n >= 2 && s.Reviews[n - 1].Rating == ReviewRating.Unsatisfactory && s.Reviews[n - 2].Rating == ReviewRating.Unsatisfactory;
        if (twoUnsat || s.Metrics.BoardConfidence < 20)
        {
            s.Outcome = GameOutcome.Terminated;
            e.Notify(MessageKind.Review, ExecRole.CEO, "Separation notice",
                "The board has lost confidence in technology leadership. Your employment as CTO ends effective today. " +
                "A transition plan for your responsibilities will be shared with the CIO.");
        }
        else if (review.Rating == ReviewRating.Unsatisfactory)
            e.Notify(MessageKind.Escalation, ExecRole.CEO, "Performance improvement plan",
                "Another quarter like this one and I will not be able to defend your position to the board.");
        return review;
    }

    public static string Label(ReviewRating r) => r switch
    {
        ReviewRating.ExceedsExpectations => "Exceeds expectations",
        ReviewRating.MeetsExpectations => "Meets expectations",
        ReviewRating.BelowExpectations => "Below expectations",
        _ => "Unsatisfactory",
    };

    /// <summary>Pure computation (no mutation) — also used for "how am I doing?" questions and claim checks.</summary>
    public static PerformanceReview Compute(GameState s, DateOnly from, DateOnly to)
    {
        var ev = new List<string>();
        var decisions = s.Decisions.Where(d => d.Date >= from && d.Date <= to).ToList();

        double dq;
        if (decisions.Count == 0) { dq = 45; ev.Add("No material decisions were made this period."); }
        else
        {
            dq = decisions.Average(d => d.Evaluation.Overall);
            ev.Add($"{decisions.Count} decisions, average decision quality {dq:0}.");
            var best = decisions.OrderByDescending(d => d.Evaluation.Overall).First();
            var worst = decisions.OrderBy(d => d.Evaluation.Overall).First();
            ev.Add($"Strongest: {best.Summary} ({best.Evaluation.Overall:0}).");
            if (worst != best) ev.Add($"Weakest: {worst.Summary} ({worst.Evaluation.Overall:0}) — {worst.Evaluation.Notes.FirstOrDefault() ?? ""}".TrimEnd(' ', '—'));
        }

        // Delivery: delegated work and projects.
        var dueAssignments = s.Assignments.Where(a => !a.IsRequest && a.Due >= from && a.Due <= to && a.Status != AssignmentStatus.Declined).ToList();
        double onTime = dueAssignments.Count == 0 ? 0.6 : dueAssignments.Count(a => a.Status == AssignmentStatus.Completed && a.CompletedOn <= a.Due) / (double)dueAssignments.Count;
        var activeProjects = s.Projects.Where(p => p.StartDate <= to && (p.ActualEndDate == null || p.ActualEndDate >= from)).ToList();
        double schedule = activeProjects.Count == 0 ? 0.6 : activeProjects.Average(p =>
        {
            double planned = Math.Clamp((to.DayNumber - p.StartDate.DayNumber) / (double)Math.Max(1, p.PlannedEndDate.DayNumber - p.StartDate.DayNumber), 0.01, 1);
            return Math.Clamp(p.Progress / planned, 0, 1.1);
        });
        double delivery = SimulationEngine.Clamp(onTime * 50 + schedule * 45);
        ev.Add(dueAssignments.Count == 0 ? "No delegated work fell due." : $"{dueAssignments.Count(a => a.Status == AssignmentStatus.Completed && a.CompletedOn <= a.Due)} of {dueAssignments.Count} delegated assignments delivered on time.");
        if (activeProjects.Count > 0) ev.Add($"{activeProjects.Count} project(s) tracking at {schedule:P0} of planned schedule.");

        // Financial stewardship: budget adherence and savings commitments.
        var tech = s.Departments.First(d => d.Id == s.Player.DepartmentId);
        decimal ytdBudget = FinancialEngine.TechBudgetYtd(s);
        decimal ytdActual = tech.BudgetLines.Sum(l => l.ActualFiscalYtd);
        double variance = ytdBudget == 0 ? 0 : (double)((ytdActual - ytdBudget) / ytdBudget);
        decimal runRateSavings = s.Savings.Where(x => x.Source == "budget_cut" && x.Recurring && x.Status is SavingsStatus.Approved or SavingsStatus.Realized).Sum(x => x.AnnualAmount);
        decimal negotiated = s.Contracts.Where(c => c.Renewed && c.Negotiated && c.AgreedUpliftPct < 0).Sum(c => -c.AnnualCost * (decimal)c.AgreedUpliftPct!.Value / (1 + (decimal)c.AgreedUpliftPct!.Value));
        decimal toward = runRateSavings + negotiated;
        double savingsScore = Math.Min(1, (double)(toward / SavingsTarget));
        double fin = SimulationEngine.Clamp(55 - variance * 400 + savingsScore * 35 - (s.Finance.TechCapitalBudgetRemaining < 0 ? 10 : 0));
        ev.Add($"Technology opex fiscal YTD {SimulationEngine.Money(ytdActual)} vs plan {SimulationEngine.Money(ytdBudget)} ({variance:+0.0%;-0.0%}).");
        ev.Add($"Recurring savings secured toward the CFO's {SimulationEngine.Money(SavingsTarget)} target: {SimulationEngine.Money(toward)}.");

        // Risk management: what actually happened plus visible exposure.
        var incidents = s.Incidents.Where(i => i.Started >= from && i.Started <= to).ToList();
        double downtime = incidents.Sum(i => i.DowntimeHours);
        int safety = incidents.Sum(i => i.SafetyEvents);
        var known = s.Risks.Where(r => r.Known && !r.Closed).ToList();
        bool addressingDr = s.Projects.Any(p => p.EffectKey.StartsWith("dr_") && p.Status != ProjectStatus.Cancelled) || s.Technology.HasSecondarySite;
        bool addressingBackup = s.Projects.Any(p => p.EffectKey == "immutable_backup") || s.Technology.ImmutableBackups;
        double risk = 60 - downtime * 0.6 - safety * 8 + (addressingDr ? 15 : -10) + (addressingBackup ? 8 : 0)
                      - known.Count(r => r.Score >= 15) * 3;
        risk = SimulationEngine.Clamp(risk);
        ev.Add(incidents.Count == 0 ? "No major incidents." : $"{incidents.Count} incident(s): {downtime:0} h downtime, {safety} patient safety events.");
        ev.Add(addressingDr ? "Disaster recovery gap is being addressed." : "Disaster recovery remains below target with no funded remediation.");

        double overall = dq * 0.35 + delivery * 0.2 + fin * 0.25 + risk * 0.2;
        double bar = s.Difficulty switch { Difficulty.Casual => -5, Difficulty.Executive => 5, _ => 0 };
        var rating = overall >= 75 + bar ? ReviewRating.ExceedsExpectations
                   : overall >= 58 + bar ? ReviewRating.MeetsExpectations
                   : overall >= 45 + bar ? ReviewRating.BelowExpectations
                   : ReviewRating.Unsatisfactory;
        string comment = rating switch
        {
            ReviewRating.ExceedsExpectations => "Strong quarter. Your decisions were well-evidenced and the results show it.",
            ReviewRating.MeetsExpectations => "Solid, but the board will want to see the major risks closed, not just discussed.",
            ReviewRating.BelowExpectations => "I need more from you. Decisions need better grounding and commitments need to land.",
            _ => "This is not the performance I need from my CTO.",
        };
        int fyQ = ((to.Month - s.FiscalYearStartMonth + 12) % 12) / 3 + 1;
        return new PerformanceReview
        {
            Date = to, Period = $"FY{FinancialEngine.FiscalYearEnd(s, to).Year % 100:00} Q{fyQ}",
            DecisionQuality = Math.Round(dq, 1), Delivery = Math.Round(delivery, 1), FinancialStewardship = Math.Round(fin, 1),
            RiskManagement = Math.Round(risk, 1), Overall = Math.Round(overall, 1), Rating = rating, Evidence = ev, ReviewerComment = comment,
        };
    }
}

/// <summary>Background drift of executive workload and morale, and institutional escalations.</summary>
public static class ExecutiveDynamics
{
    public static void DailyTick(SimulationEngine e)
    {
        var s = e.State;
        foreach (var x in s.Executives)
        {
            x.Workload = SimulationEngine.Clamp(x.Workload + (55 - x.Workload) * 0.01);
            x.Morale = SimulationEngine.Clamp(x.Morale + (65 - x.Morale) * 0.005);
        }
        if (s.CurrentDate.Day == 1) CisoEscalationCheck(e);
    }

    /// <summary>
    /// If the player keeps sitting on known, severe security/backup risk, the CISO escalates to the CEO.
    /// This is institutional memory acting on its own — not something the player can talk their way out of.
    /// </summary>
    private static void CisoEscalationCheck(SimulationEngine e)
    {
        var s = e.State;
        if (s.Memory.Any(m => m.Kind == "ciso_escalation" && s.CurrentDate.DayNumber - m.Date.DayNumber < 90)) return;
        var severe = s.Risks.Where(r => r.Known && !r.Closed && r.Topic is Topics.Backup or Topics.Security && r.Score >= 12
                                        && s.CurrentDate.DayNumber - r.Identified.DayNumber >= 45).ToList();
        if (severe.Count == 0) return;
        bool addressed = s.Projects.Any(p => p.EffectKey == "immutable_backup" && p.Status != ProjectStatus.Cancelled)
                         || s.Proposals.Any(p => p.EffectKey == "immutable_backup" && p.Status == ProposalStatus.AwaitingApproval);
        if (addressed) return;
        int dismissals = s.Decisions.Count(d => d.Action is "reject_proposal" or "defer_proposal" && d.Topic is Topics.Backup or Topics.Security);
        var ciso = s.Exec(ExecRole.CISO);
        if (dismissals == 0 && ciso.TrustInPlayer > 45) return;

        s.Metrics.BoardConfidence = SimulationEngine.Clamp(s.Metrics.BoardConfidence - 4);
        e.AdjustTrust(ExecRole.CEO, -5);
        e.AdjustTrust(ExecRole.CISO, -3);
        e.Notify(MessageKind.Escalation, ExecRole.CISO, "CISO escalation to the CEO",
            $"{ciso.Name} has formally escalated unaddressed cyber risk to the CEO and the audit committee chair: " +
            string.Join("; ", severe.Select(r => r.Title)) + ". The memo notes that remediation has been " +
            (dismissals > 0 ? $"declined or deferred {dismissals} time(s)." : "pending without a decision."));
        e.Remember("ciso_escalation", "CISO escalated unaddressed security risk to the CEO.", new[] { Topics.Security, Topics.Backup }, new[] { ExecRole.CISO, ExecRole.CEO }, 3);
    }
}
